  .hero-word { position: relative; left: auto; top: auto; transform: none; align-self: center; justify-self: center; font-size: clamp(3.4rem, 19vw, 6.5rem); margin-bottom: 1rem; z-index: 0; }
  .hero-word .sub { letter-spacing: 0.24em; }
  .hero-cut-3 { display: none; }
