/* Motion choreography (GSAP + ScrollTrigger). Every animation has a job:
   hero entry = hierarchy (word, then cutouts, then the search); cutout parallax = depth; reveals = sequence; sticky stack = the four in order; blur-on-focus = attention. */
(function () {
  const reduced = document.documentElement.classList.contains('reduced') || window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const hasGsap = typeof window.gsap !== 'undefined';

  // ----- Search focus blurs the page (CSS handles the blur; JS toggles the body class) -----
  document.querySelectorAll('[data-search]').forEach((wrap) => {
    const input = wrap.querySelector('.search-input');
    if (!input) return;
    input.addEventListener('focus', () => { document.body.classList.add('search-focus'); wrap.classList.add('is-focus'); });
    input.addEventListener('blur', () => { setTimeout(() => { if (!wrap.contains(document.activeElement)) { document.body.classList.remove('search-focus'); wrap.classList.remove('is-focus'); } }, 120); });
  });

  if (reduced || !hasGsap) {
    document.querySelectorAll('.reveal').forEach((el) => el.classList.add('is-in'));
    return;
  }
  gsap.registerPlugin(ScrollTrigger);

  // ----- Hero entry -----
  const word = document.querySelector('[data-hero-word]');
  if (word) {
    const tl = gsap.timeline({ defaults: { ease: 'expo.out' } });
    tl.from(word, { yPercent: 18, opacity: 0, duration: 1.2 }, 0)
      .from('.hero-cut', { yPercent: 12, opacity: 0, scale: 0.94, duration: 1.3, stagger: 0.08 }, 0.15)
      .from('[data-hero-in]', { y: 26, opacity: 0, filter: 'blur(8px)', duration: 0.9, stagger: 0.08 }, 0.45);

    // Pointer parallax on the cutouts (depth). Uses quickTo, no React state, no scroll listener.
    const cuts = Array.from(document.querySelectorAll('.hero-cut'));
    if (cuts.length && window.matchMedia('(pointer: fine)').matches) {
      const movers = cuts.map((c) => ({ x: gsap.quickTo(c, 'x', { duration: 0.8, ease: 'power3.out' }), y: gsap.quickTo(c, 'y', { duration: 0.8, ease: 'power3.out' }), d: parseFloat(c.dataset.depth || '0.4') }));
      const hero = document.querySelector('.hero');
      hero.addEventListener('pointermove', (e) => {
        const r = hero.getBoundingClientRect();
        const nx = (e.clientX - r.left) / r.width - 0.5, ny = (e.clientY - r.top) / r.height - 0.5;
        movers.forEach((m) => { m.x(nx * 40 * m.d); m.y(ny * 24 * m.d); });
      });
      hero.addEventListener('pointerleave', () => movers.forEach((m) => { m.x(0); m.y(0); }));
    }

