/* Smoke test for src/js/search.js. Loads hours.js and search.js into a vm context with a hand-rolled
   window/document, then exercises the ranking, the learning model and the rendered markup.
   Run: node "<this file>" */
import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';

const ROOT = 'C:/Users/Kenneth Rodas/Documents/GitHub/eatdanville';
const read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8');

const EAT_DATA = {
  site: JSON.parse(read('data/district.json')),
  restaurants: JSON.parse(read('data/restaurants.json')),
  categories: JSON.parse(read('data/categories.json')),
};

// ---------- tiny assertion harness ----------
let pass = 0;
const failures = [];
function ok(name, cond, detail) {
  if (cond) { pass++; console.log('  ok   ' + name); }
  else { failures.push(name + (detail ? ' :: ' + detail : '')); console.log('  FAIL ' + name + (detail ? ' :: ' + detail : '')); }
}
function section(name) { console.log('\n' + name); }

// ---------- fake timers ----------
const timers = { seq: 1, items: new Map() };
const setTimeoutStub = (fn, ms) => { const id = timers.seq++; timers.items.set(id, { fn, ms, kind: 'timeout' }); return id; };
const setIntervalStub = (fn, ms) => { const id = timers.seq++; timers.items.set(id, { fn, ms, kind: 'interval' }); return id; };
const clearStub = (id) => { timers.items.delete(id); };
function flushTimeouts() {
  for (let round = 0; round < 5; round++) {
    const due = [...timers.items.entries()].filter(([, t]) => t.kind === 'timeout');
    if (!due.length) return;
    due.forEach(([id, t]) => { timers.items.delete(id); t.fn(); });
  }
}
const intervals = () => [...timers.items.values()].filter((t) => t.kind === 'interval');

// ---------- fake DOM ----------
function el(tag, attrs) {
  const node = {
    tag,
    attrs: Object.assign({}, attrs),
    kids: [],
    value: '',
    scrollTop: 0,
    handlers: {},
    classes: new Set(),
    _html: '',
    _nodes: null,
  };
  node.classList = {
    add: (c) => node.classes.add(c),
    remove: (c) => node.classes.delete(c),
    contains: (c) => node.classes.has(c),
    toggle: (c, on) => { if (on === undefined) { node.classes.has(c) ? node.classes.delete(c) : node.classes.add(c); } else if (on) node.classes.add(c); else node.classes.delete(c); },
  };
  node.setAttribute = (k, v) => { node.attrs[k] = String(v); };
  node.getAttribute = (k) => (node.attrs[k] === undefined ? null : node.attrs[k]);
  node.removeAttribute = (k) => { delete node.attrs[k]; };
  node.hasAttribute = (k) => node.attrs[k] !== undefined;
  node.addEventListener = (type, fn) => { (node.handlers[type] = node.handlers[type] || []).push(fn); };
  node.fire = (type, ev) => (node.handlers[type] || []).forEach((fn) => fn(ev || { preventDefault() {}, stopPropagation() {}, target: node }));
  node.focus = () => { doc.activeElement = node; };
  node.contains = (other) => other === node || node.kids.indexOf(other) > -1;
  node.append = (child) => { node.kids.push(child); child.parent = node; return child; };
  node.matches = (sel) => match(node, sel);
  node.querySelector = (sel) => node.querySelectorAll(sel)[0] || null;
  node.querySelectorAll = (sel) => {
    if (sel === '.search-item') return optionNodes(node);
    const out = [];
    node.kids.forEach((k) => { if (match(k, sel)) out.push(k); k.querySelectorAll(sel).forEach((x) => out.push(x)); });
    return out;
  };
  Object.defineProperty(node, 'innerHTML', {
    get: () => node._html,
    set: (v) => { node._html = String(v); node._nodes = null; },
  });
  Object.defineProperty(node, 'id', {
    get: () => node.attrs.id || '',
    set: (v) => { node.attrs.id = String(v); },
  });
  Object.defineProperty(node, 'textContent', {
    get: () => node._html.replace(/<[^>]*>/g, ''),
    set: (v) => { node._html = String(v); node._nodes = null; },
  });
  return node;
}

// Options are parsed out of the panel markup once per render so setAttribute sticks.
function optionNodes(panel) {
  if (panel._nodes) return panel._nodes;
  const out = [];
  const re = /<div ([^>]*class="search-item"[^>]*)>/g;
  let m;
  while ((m = re.exec(panel._html)) !== null) {
    const attrs = {};
    const are = /([a-z-]+)="([^"]*)"/g;
    let a;
    while ((a = are.exec(m[1])) !== null) attrs[a[1]] = a[2];
    const node = el('div', attrs);
    node.classes.add('search-item');
    node.scrollIntoView = () => {};
    out.push(node);
  }
  panel._nodes = out;
  return out;
}

function match(node, sel) {
  return sel.split(/(?=[.#[])/).every((part) => {
    if (!part) return true;
    if (part[0] === '.') return node.classes.has(part.slice(1));
    if (part[0] === '#') return node.attrs.id === part.slice(1);
    if (part[0] === '[') {
      const inner = part.slice(1, -1);
      const eq = inner.indexOf('=');
      if (eq < 0) return node.attrs[inner] !== undefined;
      return node.attrs[inner.slice(0, eq)] === inner.slice(eq + 1).replace(/^"|"$/g, '');
    }
    return node.tag === part;
  });
}

const root = el('html');
const doc = {
  readyState: 'interactive',
  hidden: false,
  activeElement: null,
  documentElement: root,
  body: el('body'),
  handlers: {},
  nodes: [],
  addEventListener: (type, fn) => { (doc.handlers[type] = doc.handlers[type] || []).push(fn); },
  querySelector: (sel) => doc.querySelectorAll(sel)[0] || null,
  querySelectorAll: (sel) => doc.nodes.filter((n) => match(n, sel)),
  getElementById: (id) => doc.nodes.filter((n) => n.attrs.id === id)[0] || null,
};

const store = new Map();
const localStorage = {
  getItem: (k) => (store.has(k) ? store.get(k) : null),
  setItem: (k, v) => store.set(k, String(v)),
  removeItem: (k) => store.delete(k),
  clear: () => store.clear(),
};

let reducedMotion = true;
const win = {
  EAT_DATA,
  document: doc,
  localStorage,
  console,
  Date,
  Math,
  JSON,
  location: { pathname: '/', search: '', hash: '', href: 'https://eatdanville.com/' },
  history: { replaceState(url) {}, pushState() {} },
  matchMedia: (q) => ({ matches: /reduced-motion/.test(q) ? reducedMotion : false, addEventListener() {}, addListener() {} }),
  addEventListener() {},
  dispatchEvent() {},
  setTimeout: setTimeoutStub,
  clearTimeout: clearStub,
  setInterval: setIntervalStub,
  clearInterval: clearStub,
};
win.window = win;
win.globalThis = win;

const ctx = vm.createContext(win);
vm.runInContext(read('src/js/hours.js'), ctx, { filename: 'hours.js' });
vm.runInContext(read('src/js/search.js'), ctx, { filename: 'search.js' });

const S = win.EatSearch;
const H = win.EatHours;
const slugs = (list) => list.map((r) => r.type + ':' + (r.slug || r.title));

// ---------- 1. export shape ----------
section('Export');
['init', 'query', 'profile', 'learn', 'rank', 'boost', 'reset', 'recent'].forEach((k) => {
  ok('EatSearch.' + k + ' is a function', typeof S[k] === 'function', typeof S[k]);
});
ok('load with no DOM hooks does not throw', true);

// ---------- 2. ranking ----------
section('Ranking');
S.reset();
const late = S.query('late night tacos');
const top3 = slugs(late).slice(0, 3);
ok('late night tacos ranks Rancho Cantina in the top 3', top3.indexOf('restaurant:rancho-cantina') > -1, top3.join(' | '));
ok('late night tacos ranks the Late Night category in the top 3', top3.indexOf('category:late-night') > -1, top3.join(' | '));

const tiki = S.query('tiki');
ok('tiki returns Kaia\u2019s first', tiki[0] && tiki[0].type === 'restaurant' && tiki[0].slug === 'kaias', slugs(tiki).slice(0, 3).join(' | '));

const typo = S.query('private dinning');
const typoTop = slugs(typo);
ok('private dinning finds Private Dining first', typo[0] && typo[0].type === 'category' && typo[0].slug === 'private-dining', typoTop.slice(0, 3).join(' | '));

const apos = S.query('kaias');
ok('kaias matches Kaia\u2019s without the apostrophe', apos[0] && apos[0].slug === 'kaias', slugs(apos).slice(0, 2).join(' | '));

const hula = S.query('hula pie');
ok('hula pie finds the dish at Kaia\u2019s', hula.some((r) => /hula pie/i.test(r.title) && r.restaurant === 'kaias'), slugs(hula).slice(0, 3).join(' | '));

ok('empty query returns no results', S.query('').length === 0 && S.query('   ').length === 0);
ok('nonsense query returns nothing', S.query('zzzzqqqx').length === 0, JSON.stringify(slugs(S.query('zzzzqqqx'))));

let everyCategory = true;
let missed = '';
EAT_DATA.categories.forEach((c) => {
  const hit = slugs(S.query(c.name)).slice(0, 3).indexOf('category:' + c.slug) > -1;
  if (!hit) { everyCategory = false; missed += c.slug + ' '; }
});
ok('every category name ranks its own tile in the top 3', everyCategory, missed);

const openNow = S.query('open now');
const openCount = EAT_DATA.restaurants.filter((r) => H.isOpen(r)).length;
ok('open now returns the restaurants that are open (' + openCount + ' of 4)',
  openNow.filter((r) => r.type === 'restaurant').length === openCount || openCount === 0, slugs(openNow).slice(0, 4).join(' | '));

const shape = tiki[0];
ok('result carries type, title, slug, href, subtitle, hint, group, score',
  ['type', 'title', 'slug', 'href', 'subtitle', 'hint', 'group', 'score'].every((k) => k in shape), JSON.stringify(Object.keys(shape)));
ok('restaurant result subtitle is the live status line', shape.subtitle === H.statusLine(EAT_DATA.restaurants.find((r) => r.slug === 'kaias')), shape.subtitle);
ok('restaurant result href points at the detail page', shape.href === '/r/kaias/', shape.href);

// ---------- 3. the learning model ----------
section('Learning model');
S.reset();
const fresh = S.profile();
ok('reset gives an empty profile', Object.keys(fresh.w).length === 0 && fresh.n === 0, JSON.stringify(fresh));

const before = S.rank(EAT_DATA.restaurants, {}).map((r) => r.slug);
S.learn({ type: 'result', restaurant: 'harvest' });
const after = S.rank(EAT_DATA.restaurants, {}).map((r) => r.slug);
ok('rank moves the tapped restaurant to the front', after[0] === 'harvest' && before.indexOf('harvest') > 0,
  before.join(',') + ' -> ' + after.join(','));
ok('rank returns a new array of the same length', after.length === before.length && S.rank(EAT_DATA.restaurants, {}) !== EAT_DATA.restaurants);

const p = S.profile();
ok('profile shape is { w, n }', p && typeof p === 'object' && p.w && typeof p.w === 'object' && typeof p.n === 'number', JSON.stringify(p));
ok('profile counts the event', p.n === 1, String(p.n));
ok('restaurant feature uses the r: prefix at the learning rate', Math.abs(p.w['r:harvest'] - 0.15) < 1e-9, String(p.w['r:harvest']));
ok('daypart feature recorded', Object.keys(p.w).some((f) => f.indexOf('dp:') === 0), Object.keys(p.w).join(','));
ok('hour bucket feature recorded', Object.keys(p.w).some((f) => /^h:(morning|midday|afternoon|evening|late)$/.test(f)), Object.keys(p.w).join(','));
ok('profile persists to eat.profile.v1', !!store.get('eat.profile.v1'), String(store.get('eat.profile.v1')).slice(0, 60));

const harvest = EAT_DATA.restaurants.find((r) => r.slug === 'harvest');
ok('boost returns the affinity number', typeof S.boost(harvest) === 'number' && S.boost(harvest) > 0, String(S.boost(harvest)));
ok('boost accepts a slug', Math.abs(S.boost('harvest') - S.boost(harvest)) < 1e-9);
ok('boost of an unknown restaurant is 0', S.boost({ slug: 'nope', services: {} }) === 0);

for (let i = 0; i < 40; i++) S.learn({ type: 'result', restaurant: 'harvest', category: 'brunch' });
const trained = S.profile();
ok('weights stay bounded at 1', trained.w['r:harvest'] <= 1 && trained.w['c:brunch'] <= 1, trained.w['r:harvest'] + ' / ' + trained.w['c:brunch']);
ok('untouched features decay away', trained.w['dp:x'] === undefined);

S.learn({ type: 'category', category: 'late_night' });
ok('category feature uses the c: prefix', typeof S.profile().w['c:late_night'] === 'number', JSON.stringify(Object.keys(S.profile().w)));

const learnedFirst = S.query('brunch');
ok('a trained profile lifts the learned restaurant in search',
  learnedFirst.filter((r) => r.type === 'restaurant')[0].slug === 'harvest',
  slugs(learnedFirst).slice(0, 4).join(' | '));

S.reset();
ok('reset clears the stored profile', store.get('eat.profile.v1') === undefined && Object.keys(S.profile().w).length === 0);

// ---------- 4. recent searches ----------
section('Recent searches');
store.delete('eat.recent.v1');
['tacos', 'tiki', 'brunch', 'late night', 'private dining', 'dessert', 'mai tai', 'patio'].forEach((t) => S.recent(t));
const rec = S.recent();
ok('recent caps at 6', rec.length === 6, String(rec.length));
ok('recent is newest first', rec[0] === 'patio' && rec[1] === 'mai tai', rec.join(' | '));
ok('recent drops the oldest', rec.indexOf('tacos') === -1, rec.join(' | '));
S.recent('tiki');
ok('recent de-duplicates', S.recent().filter((x) => x === 'tiki').length === 1, S.recent().join(' | '));
ok('recent persists to eat.recent.v1', !!store.get('eat.recent.v1'));
ok('recent returns a copy', S.recent() !== S.recent());

// ---------- 5. suggestions panel ----------
section('Suggestions panel');
function searchBlock(page) {
  const wrap = el('div', page ? { 'data-search': '', 'data-page': '' } : { 'data-search': '' });
  wrap.classes.add('search');
  const form = el('form', {});
  const input = el('input', { placeholder: 'Search late night, brunch, tacos, tiki, private dining' });
  input.classes.add('search-input');
  const panel = el('div', { id: 'search-panel' });
  panel.classes.add('search-panel');
  wrap.append(form);
  wrap.append(input);
  wrap.append(panel);
  doc.nodes.push(wrap, form, input, panel);
  return { wrap, form, input, panel };
}

const home = searchBlock(false);
S.init();
home.input.fire('focus');
ok('empty query opens the panel', home.wrap.classes.has('is-open') && home.input.attrs['aria-expanded'] === 'true');
ok('empty query offers time-aware starters', /class="search-group"[^>]*>Right now</.test(home.panel.innerHTML), home.panel.innerHTML.slice(0, 120));
ok('empty query shows recent searches', /Recent</.test(home.panel.innerHTML));
ok('panel footer carries the on-device notice',
  home.panel.innerHTML.indexOf('Suggestions learn from what you tap, only on this device.') > -1);
ok('panel footer carries a kbd hint', /<kbd>Enter<\/kbd>/.test(home.panel.innerHTML));
ok('empty panel holds at most 8 options', (home.panel.innerHTML.match(/role="option"/g) || []).length <= 8,
  String((home.panel.innerHTML.match(/role="option"/g) || []).length));

home.input.value = 'tiki';
home.input.fire('input');
flushTimeouts();
const html = home.panel.innerHTML;
ok('typed query renders options', (html.match(/role="option"/g) || []).length > 0);
ok('options are grouped', /class="search-group"[^>]*>Restaurants</.test(html), html.slice(0, 200));
ok('the matched substring is wrapped in mark', /<mark>Tiki<\/mark>/.test(html), (html.match(/<mark>[^<]*<\/mark>/g) || []).join(' '));
ok('rows carry thumb, title, subtitle and hint', /class="thumb"/.test(html) && /class="t"/.test(html) && /class="s"/.test(html) && /class="k"/.test(html));
ok('at most 8 rows', (html.match(/role="option"/g) || []).length <= 8, String((html.match(/role="option"/g) || []).length));

const opts = optionNodes(home.panel);
home.input.fire('keydown', { key: 'ArrowDown', preventDefault() {}, stopPropagation() {} });
ok('ArrowDown selects the first option', optionNodes(home.panel)[0].attrs['aria-selected'] === 'true');
ok('aria-activedescendant follows the selection', home.input.attrs['aria-activedescendant'] === opts[0].attrs.id,
  home.input.attrs['aria-activedescendant'] + ' vs ' + opts[0].attrs.id);
home.input.fire('keydown', { key: 'ArrowUp', preventDefault() {}, stopPropagation() {} });
ok('ArrowUp wraps to the last option', optionNodes(home.panel).slice(-1)[0].attrs['aria-selected'] === 'true');
home.input.fire('keydown', { key: 'ArrowDown', preventDefault() {}, stopPropagation() {} });
home.input.fire('keydown', { key: 'Enter', preventDefault() {}, stopPropagation() {} });
ok('Enter on a selected restaurant navigates to its page', win.location.href === '/r/kaias/', win.location.href);
ok('activation learns the restaurant', typeof S.profile().w['r:kaias'] === 'number', JSON.stringify(Object.keys(S.profile().w)));
ok('activation records the query', S.recent()[0] === 'tiki', S.recent().join(' | '));

home.input.fire('input');
flushTimeouts();
home.input.fire('keydown', { key: 'Escape', preventDefault() {}, stopPropagation() {} });
ok('Escape closes the panel', !home.wrap.classes.has('is-open') && home.input.attrs['aria-expanded'] === 'false');

win.location.href = 'https://eatdanville.com/';
home.input.value = 'late night';
home.input.fire('input');
flushTimeouts();
home.input.fire('keydown', { key: 'Enter', preventDefault() {}, stopPropagation() {} });
ok('Enter with no selection commits free text to /search/', win.location.href === '/search/?q=late%20night', win.location.href);

home.input.value = '<img src=x onerror=alert(1)>';
home.input.fire('input');
flushTimeouts();
ok('the empty state escapes the query', home.panel.innerHTML.indexOf('<img') === -1, home.panel.innerHTML.slice(0, 160));
ok('the empty state names the query', /No match for/.test(home.panel.innerHTML));

// ---------- 6. rotating placeholder ----------
section('Rotating placeholder');
ok('no placeholder interval under prefers-reduced-motion', intervals().length === 0, String(intervals().length));
reducedMotion = false;
const second = searchBlock(false);
S.init();
const rotators = intervals();
ok('placeholder cycles at 3.5 s when motion is allowed', rotators.length === 1 && rotators[0].ms === 3500, JSON.stringify(rotators.map((t) => t.ms)));
const startPlaceholder = second.input.attrs.placeholder;
rotators[0].fn();
ok('placeholder changes on tick', second.input.attrs.placeholder !== startPlaceholder, second.input.attrs.placeholder);
second.input.value = 'tacos';
const held = second.input.attrs.placeholder;
rotators[0].fn();
ok('placeholder holds while the input has text', second.input.attrs.placeholder === held);
second.input.value = '';
timers.items.clear();

// ---------- 7. results page ----------
section('Results page');
doc.nodes.length = 0;
const page = searchBlock(true);
const results = el('div', { id: 'results' });
const intro = el('div', { id: 'results-intro' });
doc.nodes.push(results, intro);
win.location.search = '?q=late+night';
S.init();
flushTimeouts();
ok('the input is filled from ?q=', page.input.value === 'late night', page.input.value);
ok('results render into #results', /class="result"/.test(results.innerHTML), results.innerHTML.slice(0, 120));
ok('results use the .result classes', /class="thumb"/.test(results.innerHTML) && /class="why"/.test(results.innerHTML) && /class="chip"/.test(results.innerHTML));
ok('intro counts the results', /^\d+ results? for <strong>late night<\/strong>$/.test(intro.innerHTML), intro.innerHTML);
ok('category results reuse the drawer handler', /data-drawer-category="late-night"/.test(results.innerHTML), results.innerHTML.slice(0, 400));

page.input.value = 'zzzzqqqx';
page.input.fire('input');
flushTimeouts();
ok('no results says so', /^No results for <strong>zzzzqqqx<\/strong>/.test(intro.innerHTML), intro.innerHTML);
ok('no results clears the list', results.innerHTML === '');

page.input.value = '';
page.input.fire('input');
flushTimeouts();
ok('an empty query lists the four restaurants', (results.innerHTML.match(/class="result"/g) || []).length === 4,
  String((results.innerHTML.match(/class="result"/g) || []).length));

win.EatDrawer = { resultCard: (r, why, chips) => '<a class="result" data-from-drawer="' + r.slug + '">' + why + chips.join(',') + '</a>' };
page.input.value = 'tiki';
page.input.fire('input');
flushTimeouts();
ok('EatDrawer.resultCard is used when app.js is loaded', /data-from-drawer="kaias"/.test(results.innerHTML), results.innerHTML.slice(0, 200));
delete win.EatDrawer;

// ---------- 8. copy and source rules ----------
section('Copy rules');
const src = read('src/js/search.js');
ok('no em-dash or en-dash anywhere in the module', src.indexOf('\u2014') === -1 && src.indexOf('\u2013') === -1);
ok('module is ASCII only', !/[^\x00-\x7F]/.test(src));
ok('no import or export statements', !/^\s*(import|export)\s/m.test(src));
ok('no window scroll listener', src.indexOf("addEventListener('scroll'") === -1);
