  src.indexOf(read('node_modules/@phosphor-icons/core/assets/regular/clock-counter-clockwise.svg').match(/ d="([^"]+)"/)[1]) > -1);

// ---------- done ----------
console.log('\n' + pass + ' passed, ' + failures.length + ' failed');
