// How well one query token matches one indexed token, 0 to 1.
function strengthOne(q, w) {
  if (q === w) return 1;
  const lq = q.length, lw = w.length;
  if (lq >= 2 && lw > lq && w.lastIndexOf(q, 0) === 0) return 0.7 + 0.25 * (lq / lw);
  if (lq >= 4 && lw > lq && w.indexOf(q) > 0) return 0.5;
  if (lq >= 4 && lw >= 4 && Math.abs(lq - lw) <= 2) {
    const d = dl(q, w, 2);
    if (d === 1) return 0.55;
    if (d === 2) return 0.38;
  }
  if (lq >= 3 && lw >= 3 && Math.abs(lq - lw) <= 3) {
    const g = dice(q, w);
    if (g >= 0.6) return 0.3 + 0.2 * g;
  }
  return 0;
}

function strength(tok, field) {
  if (!field || !field.list.length) return 0;
  if (field.set[tok] === 1) return 1;
  let best = 0;
  for (let i = 0; i < field.list.length; i++) {
    const s = strengthOne(tok, field.list[i]);
    if (s > best) { best = s; if (best === 1) break; }
  }
  return best;
}

