1	/* EatSearch: predictive directory search over the four restaurants, the ten ways to eat and their menus.
2	   The index is built once from window.EAT_DATA. Scoring mixes exact and prefix hits on names, keyword and
3	   synonym hits, character bigram similarity (Dice) and a bounded Damerau-Levenshtein pass for typos, then
4	   adds time-aware boosts from EatHours and a small model that learns from what gets tapped.
5	   The model is a bag of feature weights in localStorage. Nothing leaves this browser. */
6	(function () {
7	  // ---------- Tuning ----------
8	  const LEARN_RATE = 0.15;      // w[f] += 0.15 * (1 - w[f]) on a touched feature
9	  const DECAY = 0.98;           // every other feature decays on each event
10	  const FLOOR = 0.004;          // weights under this are dropped so storage stays small
11	  const LEARN_SCALE = 3;        // how far the learned affinity can move a score
12	  const DEBOUNCE = 40;          // ms between keystroke and render
13	  const MAX_ITEMS = 8;          // rows in the suggestions panel
14	  const MAX_RECENT = 6;
15	  const ROTATE_MS = 3500;       // placeholder cycle
16	  const KEY_PROFILE = 'eat.profile.v1';
17	  const KEY_RECENT = 'eat.recent.v1';
18	  const FIELD_W = { name: 10, key: 5, text: 2 };
19	  const PRIOR = { restaurant: 0.9, category: 0.7, service: 0.5, dish: 0.35, drink: 0.35, dessert: 0.3 };
20	  const GROUP = {
21	    restaurant: 'Restaurants', category: 'Ways to eat', service: 'Ways to eat',
22	    dish: 'Dishes and drinks', drink: 'Dishes and drinks', dessert: 'Dishes and drinks',
23	  };
24	  const PLACEHOLDERS = [
25	    'Search late night',
26	    'Search tacos and mezcal',
27	    'Search mai tai',
28	    'Search weekend brunch',
29	    'Search private dining',
30	    'Search hula pie',
31	  ];
32	  const DAYS = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
