/* Relevance sweep: prints the top 3 for a pile of realistic queries at three moments. Not a test. */
import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';

const ROOT = 'C:/Users/Kenneth Rodas/Documents/GitHub/eatdanville';
const read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8');
const EAT_DATA = {
  site: JSON.parse(read('data/district.json')),
  restaurants: JSON.parse(read('data/restaurants.json')),
  categories: JSON.parse(read('data/categories.json')),
};
const doc = { readyState: 'interactive', hidden: false, activeElement: null, documentElement: { classList: { contains: () => false } }, querySelectorAll: () => [], querySelector: () => null, getElementById: () => null, addEventListener: () => {} };
const store = new Map();
const win = {
  EAT_DATA, document: doc, console,
  localStorage: { getItem: (k) => (store.has(k) ? store.get(k) : null), setItem: (k, v) => store.set(k, v), removeItem: (k) => store.delete(k) },
  location: { search: '' }, matchMedia: () => ({ matches: false }),
  setTimeout, clearTimeout, setInterval, clearInterval, addEventListener() {}, history: { replaceState() {} },
};
win.window = win;
const ctx = vm.createContext(win);
vm.runInContext(read('src/js/hours.js'), ctx);
vm.runInContext(read('src/js/search.js'), ctx);
const S = win.EatSearch;

const moments = [
  { label: 'Tue 12:30', at: { day: 'tue', minutes: 12 * 60 + 30, date: new Date() } },
  { label: 'Fri 20:30', at: { day: 'fri', minutes: 20 * 60 + 30, date: new Date() } },
  { label: 'Sun 10:15', at: { day: 'sun', minutes: 10 * 60 + 15, date: new Date() } },
];
const queries = [
  'late night', 'late night tacos', 'nightcap', 'tiki', 'mai tai', 'tacos', 'taco tuesday', 'pasta',
  'italian', 'farm to table', 'whiskey', 'mezcal', 'brunch', 'mimosa', 'private dining', 'private dinning',
  'buyout for 30', 'doordash', 'to go', 'off menu', 'industry night', 'foh', 'dessert', 'hula pie',
  'kaias', "kaia's", 'ramcho', 'harvest', 'incontro', 'burger', 'poke bowl', 'happy hour', 'patio',
  'dog friendly', 'kids menu', 'open now', 'catering platters', 'birthday party', 'gnocchi', 'churros',
];

let total = 0;
for (const m of moments) {
  console.log('\n=== ' + m.label + ' ===');
  for (const q of queries) {
    const t0 = process.hrtime.bigint();
    const res = S.query(q, { limit: 3, at: m.at });
    total += Number(process.hrtime.bigint() - t0) / 1e6;
    console.log(q.padEnd(18) + ' -> ' + (res.map((r) => r.type + ':' + (r.slug || r.title) + (r.type === 'dish' || r.type === 'drink' || r.type === 'dessert' ? '(' + r.title + ')' : '')).join(' | ') || '(none)'));
  }
}
console.log('\ntotal query time for ' + (queries.length * moments.length) + ' queries: ' + total.toFixed(1) + ' ms');

