function scoreEntry(e, q, at, cache) {
  let sum = 0, matched = 0;
  for (let i = 0; i < q.toks.length; i++) {
    const tok = q.toks[i];
    const sn = strength(tok, e.name, true) * FIELD_W.name;
    const sk = strength(tok, e.key, true) * FIELD_W.key;
    const st = strength(tok, e.text, false) * FIELD_W.text;
    let v = Math.max(sn, sk, st);
    let fields = 0;
    if (sn > 0) fields++;
    if (sk > 0) fields++;
    if (st > 0) fields++;
    if (fields > 1) v += 0.6;
    if (q.open && (tok === 'open' || tok === 'now') && e.restaurant && isOpenAt(e.restaurant, at, cache)) {
      v = Math.max(v, e.type === 'restaurant' ? 6 : 3);
    }
    if (v > 0) { sum += v; matched++; }
  }
  if (!matched) return 0;

  let score = sum * (0.55 + 0.45 * (matched / q.toks.length));

  // The whole title is in the query ("late night" inside "late night tacos").
  if (e.titleToks.length) {
    let full = true;
    for (let i = 0; i < e.titleToks.length && full; i++) {
      let hit = false;
      for (let j = 0; j < q.toks.length && !hit; j++) hit = strengthOne(q.toks[j], e.titleToks[i]) >= 0.5;
      full = hit;
    }
    if (full) score += 2.5;
  }
  // The query is in the title.
  if (q.norm.length >= 3 && e.titleNorm.indexOf(q.norm) === 0) score += 4;
  else if (q.norm.length >= 3 && e.titleNorm.indexOf(q.norm) > 0) score += 2.5;
  // Bigram similarity of the whole phrase against the whole title.
  const g = dice(q.flat, e.titleFlat);
  if (g > 0.45) score += 3 * g;

  score += e.prior;
  score += timeBoost(e, at, cache);
  score += LEARN_SCALE * learnedBoost(e);
  return score > 0 ? score : 0;
}

