641	  function highlight(title, toks) {
642	    const raw = String(title == null ? '' : title);
643	    if (!toks || !toks.length) return esc(raw);
644	    const low = raw.toLowerCase().replace(/[\u2018\u2019\u02bc]/g, "'");
645	    const marks = [];
646	    for (let i = 0; i < toks.length; i++) {
647	      const bare = toks[i].replace(/'/g, '');
648	      if (bare.length < 2 || !/^[a-z0-9]+$/.test(bare)) continue;
649	      const re = new RegExp(bare.split('').join("'?"), 'g');
650	      let m;
651	      while ((m = re.exec(low)) !== null) {
652	        if (!m[0].length) { re.lastIndex++; continue; }
653	        const start = m.index;
654	        const before = start === 0 ? '' : low.charAt(start - 1);
655	        if (start === 0 || !/[a-z0-9]/.test(before) || bare.length >= 4) marks.push([start, start + m[0].length]);
656	      }
657	    }
658	    if (!marks.length) return esc(raw);
659	    marks.sort((a, b) => a[0] - b[0] || b[1] - a[1]);
660	    const merged = [];
661	    for (let i = 0; i < marks.length; i++) {
662	      const last = merged[merged.length - 1];
663	      if (last && marks[i][0] <= last[1]) { if (marks[i][1] > last[1]) last[1] = marks[i][1]; }
664	      else merged.push([marks[i][0], marks[i][1]]);
665	    }
666	    let out = '', pos = 0;
667	    for (let i = 0; i < merged.length; i++) {
668	      out += esc(raw.slice(pos, merged[i][0])) + '<mark>' + esc(raw.slice(merged[i][0], merged[i][1])) + '</mark>';
669	      pos = merged[i][1];
670	    }
671	    return out + esc(raw.slice(pos));
672	  }
